    except AttributeError: pass
    else: Generator.register(_cython_generator_type)
if _cython_coroutine_type is not None:
    try: Coroutine = _module.Coroutine
    except AttributeError: pass
    else: Coroutine.register(_cython_coroutine_type)

() => {
        const out = {};

        // ── 숫자 정규화 헬퍼 (IT/ES 로케일: 천단위 '.', 소수 ',') ──────────
        const txt = (sel, attr) => {
            const el = document.querySelector(sel);
            if (!el) return null;
            const v = attr ? el.getAttribute(attr) : el.textContent;
            return v ? v.trim() : null;
        };
        const parsePrice = (t) => {
            if (!t) return null;
            let s = t.replace(/[^0-9.,]/g, '');
            if (!s) return null;
            if (s.includes('.') && s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
            else if (s.includes(',')) s = s.replace(',', '.');
            const f = parseFloat(s);
            return isNaN(f) ? null : String(f);
        };
        const parseRating = (t) => {
            if (!t) return null;
            const m = t.replace(',', '.').match(/([0-5](?:\.\d+)?)/);
            return m ? parseFloat(m[1]) : null;
        };
        const parseInt10 = (t) => {
            if (!t) return null;
            const d = t.replace(/[^0-9]/g, '');
            return d ? parseInt(d, 10) : null;
        };

        // ── 1순위: JSON-LD Product (있으면 가장 신뢰도 높음) ────────────────
        for (const s of document.querySelectorAll('script[type="application/ld+json"]')) {
            try {
                const data = JSON.parse(s.innerText);
                const nodes = Array.isArray(data) ? data : (data['@graph'] || [data]);
                for (const n of nodes) {
                    if (!n || n['@type'] !== 'Product') continue;
                    let offers = n.offers || {};
                    if (Array.isArray(offers)) offers = offers[0] || {};
                    if (offers.price != null && out.price == null) out.price = String(offers.price);
                    if (offers.availability && out.inventory == null)
                        out.inventory = String(offers.availability).split('/').pop();
                    const agg = n.aggregateRating || {};
                    if (agg.ratingValue != null && out.rating == null) out.rating = Number(agg.ratingValue);
                    if ((agg.reviewCount != null || agg.ratingCount != null) && out.review_count == null)
                        out.review_count = Number(agg.reviewCount || agg.ratingCount);
                }
            } catch (e) {}
        }

        // ── 2순위: Amazon DOM 셀렉터 fallback (JSON-LD 부재 PDP 대응) ───────
        // ⚠️ 반드시 core 가격 컨테이너로 스코프. 전역 '.a-price .a-offscreen' 은
        //    액세서리/보증플랜 가격을 잘못 집으므로 금지. (품절이면 가격 null 이 정답)
        if (out.price == null) {
            out.price = parsePrice(
                txt('#corePriceDisplay_desktop_feature_div .a-price .a-offscreen') ||
                txt('#corePrice_feature_div .a-price .a-offscreen') ||
                txt('#corePrice_feature_div .a-offscreen') ||
                txt('#priceblock_ourprice') ||
                txt('#priceblock_dealprice') ||
                txt('#sns-base-price .a-offscreen')
            );
        }
        if (out.discount_price == null) {
            // 정가(취소선)와 현재가가 함께 있으면 취소선이 '원가', 위 price 가 '할인가'.
            const basis = parsePrice(
                txt('#corePriceDisplay_desktop_feature_div .basisPrice .a-offscreen') ||
                txt('#corePriceDisplay_desktop_feature_div span[data-a-strike="true"] .a-offscreen') ||
                txt('#corePrice_feature_div .basisPrice .a-offscreen')
            );
            if (basis != null && out.price != null && basis !== out.price) {
                out.discount_price = out.price;   // 현재(할인) 가격
                out.price = basis;                // 원가
            }
        }
        if (out.inventory == null) {
            // #availability 하위엔 인라인 <script> 가 섞여 있어 span 통째 textContent 는
            // 스크립트가 새어든다 → 재고 상태 클래스 span 만 정확히 집는다.
            const av = document.querySelector(
                '#availability .a-color-success, #availability .a-color-price, ' +
                '#availability .a-color-state, #availability .a-size-medium'
            );
            let s = (av ? av.textContent : (txt('#deliveryBlockMessage') || ''));
            s = s.replace(/\s+/g, ' ').trim();
            out.inventory = s ? s.slice(0, 120) : null;
        }
        if (out.rating == null) {
            out.rating = parseRating(
                txt('#acrPopover', 'title') ||
                txt('#averageCustomerReviews .a-icon-alt') ||
                txt('span[data-hook="rating-out-of-text"]') ||
                txt('i.a-icon-star .a-icon-alt')
            );
        }
        if (out.review_count == null) {
            out.review_count = parseInt10(
                txt('#acrCustomerReviewText') ||
                txt('[data-hook="total-review-count"]')
            );
        }
        return out;
    }

() => {
        // 로케일 무관 최강 신호: CAPTCHA 검증 폼
        if (document.querySelector('form[action*="validateCaptcha"]')) return true;
        const t = (document.title || '').toLowerCase();
        if (t.includes('robot check') || t.includes('inserisci i caratteri')) return true;
        const b = (document.body ? document.body.innerText : '').slice(0, 800).toLowerCase();
        return b.includes('inserisci i caratteri che vedi')
            || b.includes('non sei un robot')
            || b.includes('continua con gli acquisti')
            || b.includes('to discuss automated access');
    }
